// ─── Announcements ───────────────────────────────────────────────────────────

/**
 * Fetch active public announcements.
 * Evaluates starts_at / expires_at against the current browser time so expired
 * announcements disappear without a rebuild.
 */
export async function getAnnouncements(): Promise<Announcement[]> {
  const now = Date.now();
  return snapshot.announcements.filter((a) => {
    // If the announcement has time fields, evaluate them in the browser.
    if (a.startsAt || a.expiresAt) {
      return isAnnouncementVisible(a, now);
    }
    // Seed announcements use the `active` flag.
    return a.active;
  });
}

// ─── Site settings ──────────────────────────────────────────────────────────

/**
 * Fetch site settings (contact email, phone, social, etc.).
 * Returns null when not available (seed fallback).
 */
export async function getSiteSettings(): Promise<SiteSettingsSnapshot | null> {
  return snapshot.siteSettings;
}

// ─── Sections ────────────────────────────────────────────────────────────────

/**
 * Look up a published section from the snapshot by its registry key.
 * Returns undefined when no published row exists for the key (the public
 * component should then fall back to its built-in default copy via the
 * section registry's fallbackBehaviour).
 */
export function getSection(key: string): SectionSnapshot | undefined {
  return (snapshot.sections ?? []).find((s) => s.key === key && s.state === 'published');
}

/**
 * All published sections (for the portal content list page).
 */
export async function getAllSections(): Promise<SectionSnapshot[]> {
  return snapshot.sections ?? [];
}

// ─── Past editions ───────────────────────────────────────────────────────────

/**
 * Past editions for the About page timeline, newest-first.
 * Returns only published editions whose computed status is 'past'.
 * Returns an empty array when none exist — the About page hides the timeline.
 */
export async function getPastEditions(): Promise<PastEditionSnapshot[]> {
  // Prefer live localStorage cache so organizer edits appear immediately.
  const cached = getCachedLiveSnapshot();
  const source = cached?.pastEditions?.length ? cached.pastEditions : (snapshot.pastEditions ?? []);
  return source.filter((e) => e.state === 'published') as PastEditionSnapshot[];
}

// ─── Form submissions (via Edge Function) ────────────────────────────────────

interface SubmitResponse {
  success: boolean;
  message?: string;
  error?: string;
  id?: string;
}

/**
 * Call the submit-message Edge Function with a contact or sponsor_inquiry payload.
 */
async function callSubmitFunction(payload: Record<string, unknown>): Promise<SubmitResponse> {
  if (!SUBMIT_ENDPOINT) {
    throw new Error('SUBMIT_UNAVAILABLE');
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 20000); // 20s timeout

  try {
    const res = await fetch(SUBMIT_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(ANON_KEY ? { apikey: ANON_KEY } : {}),
      },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });

    const data = await res.json().catch(() => ({ success: false, error: 'Invalid response' }));
    if (!res.ok) {
      return { success: false, error: data.error || `HTTP ${res.status}` };
    }
    return data as SubmitResponse;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Submit general public inquiries via the submit-message Edge Function.
 */
export async function submitContact(
  payload: ContactFormPayload
): Promise<{ success: boolean; message: string; inquiryId: string }> {
  const res = await callSubmitFunction({ kind: 'contact', ...payload });

  if (!res.success) {
    throw new Error(res.error || 'Submission failed');
  }

  return {
    success: true,
    message: res.message || 'Thank you for reaching out to the Department of Tourism. Your inquiry has been logged.',
    inquiryId: res.id || `INQ-${Date.now().toString(36).toUpperCase()}`,
  };
}

/**
 * Submit sponsorship proposals via the submit-message Edge Function.
 */
export async function submitSponsorInquiry(
  payload: SponsorInquiryPayload
): Promise<{ success: boolean; message: string; proposalId: string }> {
  const res = await callSubmitFunction({ kind: 'sponsor_inquiry', ...payload });

  if (!res.success) {
    throw new Error(res.error || 'Submission failed');
  }

  return {
    success: true,
    message: res.message || 'Thank you for your partnership interest. The organizing committee will review your proposal.',
    proposalId: res.id || `SPON-${Date.now().toString(36).toUpperCase()}`,
  };
}
